using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using SupermarketCatalog.Data;using SupermarketCatalog.Models;
namespace SupermarketCatalog.Pages.Admin;
[Authorize]public class IndexModel(AppDbContext db,UserManager<StoreUser> users):PageModel{public List<Deal> Deals{get;set;}=[];public async Task OnGetAsync(){var u=await users.GetUserAsync(User);if(u is null)return;var sid=await db.Stores.Where(x=>x.OwnerId==u.Id).Select(x=>(int?)x.Id).FirstOrDefaultAsync();if(sid is not null)Deals=await db.Deals.Where(x=>x.StoreId==sid).OrderByDescending(x=>x.Id).ToListAsync();}public async Task<IActionResult> OnPostDeleteAsync(int id){var u=await users.GetUserAsync(User);var store=await db.Stores.SingleOrDefaultAsync(x=>x.OwnerId==u!.Id);var deal=await db.Deals.SingleOrDefaultAsync(x=>x.Id==id&&x.StoreId==store!.Id);if(deal is not null){db.Deals.Remove(deal);if(u!.ActiveDealsCount>0)u.ActiveDealsCount--;await db.SaveChangesAsync();}return RedirectToPage();}}